<script setup>
import {ref,computed} from 'vue';import {Head,Link,router,useForm} from '@inertiajs/vue3';import AnalyticsPanel from '../Components/AnalyticsPanel.vue';import AnalyticsFilters from '../Components/AnalyticsFilters.vue';import Errors from '../Components/Errors.vue';import {art,date} from '../art';
const props=defineProps({users:Array,student:Number,stats:Object,catalog:Object,filters:Object,audits:Array,assignments:Array,engagement:Object});
const create=useForm({username:'',password:'password',cohort:''}),editing=ref(null),update=useForm({disabled:false,cohort:'',password:''});
function edit(u){editing.value=u;update.disabled=u.disabled;update.cohort=u.cohort||'';update.password=''}
function save(){update.patch('/admin/users/'+editing.value.id,{onSuccess:()=>{editing.value=null;update.reset('password')},preserveScroll:true})}
const csvUrl=computed(()=>'/admin/analytics.csv?'+new URLSearchParams({...props.filters,student:props.student}));
function selected(e){router.get('/admin',{student:e.target.value})}
</script><template><Head title="Head Chef"/><div class="page-title"><div><p class="eyebrow">Administrator workspace</p><h1>Head Chef</h1><p>Manage your learners, question catalog, and assigned exams.</p></div><img class="portrait" :src="art.chef" alt="SUSHI head chef"></div>
<div class="row spaced"><Link class="button primary" href="/admin/overview">Cohort overview and focused practice</Link><Link class="button" href="/admin/reports">Chef’s Review · question feedback</Link><Link class="button" href="/admin/questions">Manage questions and imports</Link><Link class="button" href="/exams">Build and assign an exam</Link></div>
<section class="panel"><h2>Your learners</h2><div class="table-wrap"><table class="learner-table"><thead><tr><th>Username</th><th>Role</th><th>Cohort</th><th>Last study activity</th><th>Access</th><th></th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td data-label="Username">{{u.username}}</td><td data-label="Role">{{u.role}}</td><td data-label="Cohort">{{u.cohort||'Unassigned'}}</td><td data-label="Last study activity">{{date(u.last_active_at)}}</td><td data-label="Access">{{u.disabled?'Disabled':'Active'}}</td><td><button @click="edit(u)">Manage</button></td></tr></tbody></table></div>
<form v-if="editing" @submit.prevent="save" class="inset"><h3>Manage {{editing.username}}</h3><div class="form-grid"><label>Cohort<input v-model="update.cohort"></label><label>New temporary password (optional)<input v-model="update.password" type="password" autocomplete="new-password"></label><label class="check"><input v-model="update.disabled" type="checkbox">Disable access</label></div><Errors :errors="update.errors"/><button class="primary" :disabled="update.processing">Save changes</button><button class="plain" type="button" @click="editing=null">Cancel</button></form>
<details><summary>Add a student</summary><form @submit.prevent="create.post('/admin/users',{onSuccess:()=>create.reset(),preserveScroll:true})"><div class="form-grid"><label>Username<input v-model="create.username" required pattern="[a-z0-9_]{3,40}"></label><label>Temporary password<input v-model="create.password" type="password" minlength="8" required autocomplete="new-password"></label><label>Cohort<input v-model="create.cohort"></label></div><Errors :errors="create.errors"/><button :disabled="create.processing">Create student</button></form></details></section>
<section class="panel"><h2>Learner analytics</h2><label>Student<select :value="student" @change="selected"><option v-for="u in users.filter(u=>u.role==='student')" :value="u.id">{{u.username}}</option></select></label><p>Each student's results are shown separately. Administrator practice is excluded from the learner selector.</p><a v-if="student" class="button" :href="csvUrl">Download filtered CSV</a></section>
<section v-if="engagement" class="panel"><h2>Daily habits and achievements</h2><div class="stat-grid"><div class="stat"><strong>{{engagement.habits.current}}</strong><span>Current streak · longest {{engagement.habits.longest}}</span></div><div class="stat"><strong>{{engagement.last_seven_days}}</strong><span>Catch completions in the last seven days</span></div><div class="stat"><strong>{{engagement.badges}}</strong><span>Passport achievements</span></div></div><p>{{engagement.reminders_sent}} reminder-days sent · {{engagement.reminders_clicked}} clicked. A sent notification is not a confirmed read.</p><h3>Study activity</h3><div v-for="m in engagement.activity" :key="m.mode" class="row"><strong>{{m.mode}}</strong><span>{{m.questions}} distinct questions · {{m.answers}} graded answers</span></div><h3 class="spaced">Current familiarity ratings</h3><div class="pin-tags"><span v-for="r in engagement.confidence" :key="r.confidence">Rating {{r.confidence||'unrated'}}: {{r.total}}</span></div></section>
<AnalyticsFilters :key="student" :catalog="catalog" :filters="filters" path="/admin" :student="student"/><AnalyticsPanel :stats="stats" admin/>
<section v-if="assignments.length" class="panel"><h2>Assigned exams</h2><div v-for="a in assignments" :key="a.id" class="row"><span>{{a.exam.title}} · {{a.user.username}}</span><label class="check"><input type="checkbox" :checked="a.release_answers" @change="router.patch('/admin/assignments/'+a.id,{release_answers:$event.target.checked},{preserveScroll:true})">Release answer explanations</label></div></section>
<section class="panel"><h2>Recent management activity</h2><p v-if="!audits.length">Management actions will appear here.</p><div v-for="a in audits" :key="a.id" class="row"><span>{{a.action}} · {{a.target}}</span><small>{{date(a.created_at)}}</small></div></section>
</template>
